__attribute__((unused)) static void
numa_migr__assert(struct numa_migr *s __attribute__((unused)))
{
#ifdef __cplusplus
#define _Static_assert static_assert
#endif
	_Static_assert(sizeof(s->rodata->nr_nodes) == 4, "unexpected size of 'nr_nodes'");
	_Static_assert(sizeof(s->rodata->target_tgid) == 4, "unexpected size of 'target_tgid'");
	_Static_assert(sizeof(s->rodata->migrate_interval_ns) == 8, "unexpected size of 'migrate_interval_ns'");
	_Static_assert(sizeof(s->rodata->cpu_node) == 512, "unexpected size of 'cpu_node'");
	_Static_assert(sizeof(s->rodata->node_ncpus) == 16, "unexpected size of 'node_ncpus'");
	_Static_assert(sizeof(s->rodata->node_cpus) == 4096, "unexpected size of 'node_cpus'");
	_Static_assert(sizeof(s->bss->stat_runs) == 8, "unexpected size of 'stat_runs'");
	_Static_assert(sizeof(s->bss->stat_cpu_migrations) == 8, "unexpected size of 'stat_cpu_migrations'");
	_Static_assert(sizeof(s->bss->stat_node_migrations) == 8, "unexpected size of 'stat_node_migrations'");
	_Static_assert(sizeof(s->bss->stat_forced_moves) == 8, "unexpected size of 'stat_forced_moves'");
	_Static_assert(sizeof(s->bss->exited) == 8, "unexpected size of 'exited'");
	_Static_assert(sizeof(s->bss->exit_kind) == 8, "unexpected size of 'exit_kind'");
	_Static_assert(sizeof(s->bss->exit_code) == 8, "unexpected size of 'exit_code'");
	_Static_assert(sizeof(s->bss->exit_reason) == 128, "unexpected size of 'exit_reason'");
	_Static_assert(sizeof(s->bss->exit_msg) == 256, "unexpected size of 'exit_msg'");
#ifdef __cplusplus
#undef _Static_assert
#endif
}

